<script setup lang="ts">
import BaseIcon from '@/shared/components/BaseIcon.vue';
import AppShell from '@/shared/layouts/AppShell.vue';
import { Head, useForm } from '@inertiajs/vue3';
import { computed, ref, watch } from 'vue';
import { ChevronDown } from 'lucide-vue-next';

type Invoice = { id: number; number: string; type: string; status: string; payer_type: string; coverage_name: string | null; total_amount: string; paid_amount: string; issued_at: string };
type Location = { id: number; name: string; legal_entity_id: number };
type Patient = { id: number; first_name: string; last_name: string; coverage_name: string };
type PaymentMethod = { id: number; legal_entity_id: number; name: string };
type CashRegister = { id: number; location_id: number; opening_amount: string; opened_at: string | null };
type CashClosure = { id: number; opening_amount: string; expected_amount: string; counted_amount: string; difference_amount: string; closed_at: string };
type JournalEntry = { id: number; entry_date: string; description: string; lines: Array<{ id: number; debit: string; credit: string; account: { code: string; name: string } }> };
type AccountBalance = { id: number; code: string; name: string; debits: string; credits: string };
type Refund = { id: number; amount: string; reason: string; status: string; invoice: { number: string } };

const props = defineProps<{
    invoices: Invoice[];
    cashRegisters: CashRegister[];
    locations: Location[];
    patients: Patient[];
    paymentMethods: PaymentMethod[];
    cashClosures: CashClosure[];
    refunds: Refund[];
    journalEntries: JournalEntry[];
    accountBalances: AccountBalance[];
    permissions: { canManageAccounting: boolean; canIssueInvoices: boolean; canRecordPayments: boolean; canOperateCash: boolean; canCancelInvoices: boolean };
}>();

const section = ref<'operations' | 'accounting'>(new URLSearchParams(window.location.search).get('seccion') === 'contabilidad' ? 'accounting' : 'operations');
const invoicePanelOpen = ref(false);
const paymentPanelOpen = ref(false);
const cashPanelOpen = ref(false);
const cancelTarget = ref<Invoice | null>(null);
const adjustmentTarget = ref<Invoice | null>(null);
const adjustmentType = ref<'credit-note' | 'refund'>('credit-note');
const invoiceForm = useForm({ location_id: props.locations[0]?.id ?? '', patient_id: '', payer_type: 'patient', coverage_name: '', coverage_amount: 0, type: 'invoice', items: [{ description: '', quantity: 1, unit_price: 0, tax_rate: 0 }] });
const paymentForm = useForm({ invoice_id: '', payment_method_id: '', amount: 0, reference: '' });
const cashForm = useForm({ location_id: props.locations[0]?.id ?? '', opening_amount: 0, counted_amount: 0 });
const cancelForm = useForm({ reason: '' });
const adjustmentForm = useForm({ amount: 0, reason: '' });
const refundActionForm = useForm({});

const currency = (amount: string | number): string => new Intl.NumberFormat('es-AR', {
    style: 'currency', currency: 'ARS',
}).format(Number(amount));

const invoiceTotal = computed(() => invoiceForm.items.reduce((total, item) => total + Number(item.quantity || 0) * Number(item.unit_price || 0) * (1 + Number(item.tax_rate || 0) / 100), 0));
const selectedCashRegister = computed(() => props.cashRegisters.find((item) => item.location_id === Number(cashForm.location_id)));
const statusClass = (status: string): string => status === 'paid' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-300' : status === 'canceled' ? 'bg-rose-100 text-rose-700 dark:bg-rose-950/50 dark:text-rose-300' : 'bg-amber-100 text-amber-700 dark:bg-amber-950/50 dark:text-amber-300';
const statusLabel = (status: string): string => ({ issued: 'Emitida', paid: 'Cobrada', canceled: 'Anulada' }[status] ?? status);
const payerLabel = (payer: string): string => ({ patient: 'Paciente', coverage: 'Cobertura', mixed: 'Mixto' }[payer] ?? payer);
const addItem = (): void => {
    invoiceForm.items.push({ description: '', quantity: 1, unit_price: 0, tax_rate: 0 });
};
const removeItem = (index: number): void => { if (invoiceForm.items.length > 1) invoiceForm.items.splice(index, 1); };
const submitInvoice = (): void => invoiceForm.post('/facturacion/facturas', { preserveScroll: true, onSuccess: () => { invoicePanelOpen.value = false; invoiceForm.reset(); invoiceForm.items = [{ description: '', quantity: 1, unit_price: 0, tax_rate: 0 }]; } });
const submitPayment = (): void => paymentForm.post('/facturacion/cobros', { preserveScroll: true, onSuccess: () => { paymentPanelOpen.value = false; paymentForm.reset(); } });
const submitCash = (): void => { const action = selectedCashRegister.value?.opened_at ? 'cierre' : 'apertura'; cashForm.post(`/facturacion/cajas/${cashForm.location_id}/${action}`, { preserveScroll: true, onSuccess: () => { cashPanelOpen.value = false; cashForm.reset(); } }); };
const submitCancellation = (): void => { if (cancelTarget.value) cancelForm.post(`/facturacion/facturas/${cancelTarget.value.id}/anulacion`, { preserveScroll: true, onSuccess: () => { cancelTarget.value = null; cancelForm.reset(); } }); };
const openAdjustment = (invoice: Invoice, type: 'credit-note' | 'refund'): void => {
    adjustmentTarget.value = invoice;
    adjustmentType.value = type;
    adjustmentForm.reset();
    adjustmentForm.amount = type === 'refund' ? Number(invoice.paid_amount) : Number(invoice.total_amount);
};
const submitAdjustment = (): void => {
    if (!adjustmentTarget.value) return;

    const endpoint = adjustmentType.value === 'credit-note'
        ? `/facturacion/facturas/${adjustmentTarget.value.id}/notas-de-credito`
        : `/facturacion/facturas/${adjustmentTarget.value.id}/devoluciones`;
    adjustmentForm.post(endpoint, { preserveScroll: true, onSuccess: () => { adjustmentTarget.value = null; adjustmentForm.reset(); } });
};
const authorizeRefund = (refund: Refund): void => refundActionForm.post(`/facturacion/devoluciones/${refund.id}/autorizar`, { preserveScroll: true });
const registerRefund = (refund: Refund): void => refundActionForm.post(`/facturacion/devoluciones/${refund.id}/registrar`, { preserveScroll: true });

watch(() => invoiceForm.payer_type, (payerType) => { if (payerType === 'coverage') invoiceForm.coverage_amount = invoiceTotal.value; if (payerType === 'patient') { invoiceForm.coverage_amount = 0; invoiceForm.coverage_name = ''; } });
watch(invoiceTotal, (total) => { if (invoiceForm.payer_type === 'coverage') invoiceForm.coverage_amount = total; });
</script>

<template>
    <Head title="Facturación" />
    <AppShell title="Facturación y contabilidad" eyebrow="Administración" description="Operación de comprobantes, caja y consulta contable por sede.">
        <div class="flex flex-wrap gap-2 border-b border-slate-200 pb-4 dark:border-slate-800">
            <button type="button" class="min-h-10 rounded-xl px-4 text-sm font-semibold transition" :class="section === 'operations' ? 'bg-clinic-600 text-white shadow-md shadow-clinic-600/20' : 'text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800'" @click="section = 'operations'">Operación</button>
            <button v-if="permissions.canManageAccounting" type="button" class="min-h-10 rounded-xl px-4 text-sm font-semibold transition" :class="section === 'accounting' ? 'bg-clinic-600 text-white shadow-md shadow-clinic-600/20' : 'text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800'" @click="section = 'accounting'">Contabilidad</button>
        </div>

        <template v-if="section === 'operations'">
        <section class="mt-6 grid gap-4 md:grid-cols-4">
            <article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
                <p class="text-sm text-slate-500 dark:text-slate-400">Comprobantes recientes</p>
                <p class="mt-2 text-3xl font-bold text-slate-950 dark:text-white">{{ invoices.length }}</p>
            </article>
            <article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
                <p class="text-sm text-slate-500 dark:text-slate-400">Cajas abiertas</p>
                <p class="mt-2 text-3xl font-bold text-slate-950 dark:text-white">{{ cashRegisters.filter((cashRegister) => cashRegister.opened_at).length }}</p>
            </article>
            <article class="rounded-2xl border border-amber-200 bg-amber-50 p-5 dark:border-amber-900/60 dark:bg-amber-950/20">
                <p class="text-sm font-medium text-amber-900 dark:text-amber-200">ARCA</p>
                <p class="mt-2 text-sm leading-6 text-amber-800 dark:text-amber-300">La emisión electrónica se habilitará al completar el punto de venta y las credenciales fiscales.</p>
            </article>
        </section>

        <section class="mt-6 flex flex-wrap gap-3">
            <button v-if="permissions.canIssueInvoices" type="button" class="inline-flex min-h-11 items-center gap-2 rounded-xl bg-clinic-600 px-4 text-sm font-semibold text-white shadow-md shadow-clinic-600/20 hover:bg-clinic-700" @click="invoicePanelOpen = !invoicePanelOpen"><BaseIcon name="plus" class="size-4" /> Nueva factura</button>
            <button v-if="permissions.canRecordPayments" type="button" class="inline-flex min-h-11 items-center gap-2 rounded-xl border border-slate-300 bg-white px-4 text-sm font-semibold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:bg-slate-800" @click="paymentPanelOpen = !paymentPanelOpen"><BaseIcon name="wallet" class="size-4" /> Registrar cobro <ChevronDown :class="['h-4 w-4 transition-transform', paymentPanelOpen ? 'rotate-180' : '']" /> </button>
            <button v-if="permissions.canOperateCash" type="button" class="inline-flex min-h-11 items-center gap-2 rounded-xl border border-slate-300 bg-white px-4 text-sm font-semibold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:bg-slate-800" @click="cashPanelOpen = !cashPanelOpen"><BaseIcon name="receipt" class="size-4" /> Abrir / cerrar caja <ChevronDown :class="['h-4 w-4 transition-transform', cashPanelOpen ? 'rotate-180' : '']" /> </button>
        </section>

        <form v-if="invoicePanelOpen" class="mt-6 rounded-2xl border border-clinic-200 bg-white p-5 shadow-sm dark:border-clinic-900/60 dark:bg-slate-900" @submit.prevent="submitInvoice">
            <div class="flex items-start justify-between gap-4"><div><h2 class="font-semibold text-slate-950 dark:text-white">Nuevo comprobante</h2><p class="mt-1 text-sm text-slate-500 dark:text-slate-400">La contabilización se genera automáticamente al emitir.</p></div><button type="button" class="rounded-lg p-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800" @click="invoicePanelOpen = false"><BaseIcon name="close" class="size-4" /></button></div>
            <div class="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                <label class="text-sm font-medium text-slate-700 dark:text-slate-200">Sede<select v-model="invoiceForm.location_id" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950"><option value="">Seleccionar</option><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.name }}</option></select></label>
                <label class="text-sm font-medium text-slate-700 dark:text-slate-200">Paciente<select v-model="invoiceForm.patient_id" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950"><option value="">Consumidor final</option><option v-for="patient in patients" :key="patient.id" :value="patient.id">{{ patient.last_name }}, {{ patient.first_name }}</option></select></label>
                <label class="text-sm font-medium text-slate-700 dark:text-slate-200">Comprobante<select v-model="invoiceForm.type" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950"><option value="invoice">Factura</option><option value="advance">Anticipo</option></select></label>
                <label class="text-sm font-medium text-slate-700 dark:text-slate-200">Pagador<select v-model="invoiceForm.payer_type" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950"><option value="patient">Paciente</option><option value="coverage">Cobertura</option><option value="mixed">Paciente y cobertura</option></select></label>
                <label v-if="invoiceForm.payer_type !== 'patient'" class="text-sm font-medium text-slate-700 dark:text-slate-200">Cobertura<input v-model="invoiceForm.coverage_name" type="text" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950" placeholder="Obra social o prepaga" /></label>
                <label v-if="invoiceForm.payer_type !== 'patient'" class="text-sm font-medium text-slate-700 dark:text-slate-200">Importe cobertura<input v-model.number="invoiceForm.coverage_amount" type="number" min="0" step="0.01" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950" /></label>
            </div>
            <div class="mt-6 rounded-xl bg-slate-50 p-4 dark:bg-slate-950/60"><div class="mb-3 flex items-center justify-between"><h3 class="text-sm font-semibold text-slate-900 dark:text-white">Conceptos</h3><button type="button" class="text-sm font-semibold text-clinic-700 dark:text-clinic-300" @click="addItem">Agregar concepto</button></div><div v-for="(item, index) in invoiceForm.items" :key="index" class="mb-3 grid gap-3 md:grid-cols-[1fr_110px_150px_110px_auto]"><input v-model="item.description" type="text" class="min-h-11 rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-900" placeholder="Descripción" /><input v-model.number="item.quantity" type="number" min="0.01" step="0.01" class="min-h-11 rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-900" placeholder="Cant." /><input v-model.number="item.unit_price" type="number" min="0" step="0.01" class="min-h-11 rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-900" placeholder="Precio" /><input v-model.number="item.tax_rate" type="number" min="0" max="100" step="0.01" class="min-h-11 rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-900" placeholder="IVA %" /><button type="button" class="min-h-11 rounded-xl px-3 text-rose-600 hover:bg-rose-50" @click="removeItem(index)"><BaseIcon name="close" class="size-4" /></button></div></div>
            <div class="mt-5 flex flex-col gap-4 border-t border-slate-200 pt-4 sm:flex-row sm:items-center sm:justify-between dark:border-slate-800"><p class="text-lg font-bold text-slate-950 dark:text-white">Total: {{ currency(invoiceTotal) }}</p><button type="submit" :disabled="invoiceForm.processing" class="min-h-11 rounded-xl bg-clinic-600 px-5 text-sm font-semibold text-white hover:bg-clinic-700 disabled:opacity-60">Emitir comprobante</button></div>
        </form>

        <form v-if="paymentPanelOpen" class="mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900" @submit.prevent="submitPayment"><div class="flex items-start justify-between gap-4"><div><h2 class="font-semibold text-slate-950 dark:text-white">Registrar cobro</h2><p class="mt-1 text-sm text-slate-500 dark:text-slate-400">El asiento de cobranza se genera automáticamente.</p></div><button type="button" class="rounded-lg p-2 text-slate-500 hover:bg-slate-100" @click="paymentPanelOpen = false"><BaseIcon name="close" class="size-4" /></button></div><div class="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label class="text-sm font-medium text-slate-700 dark:text-slate-200">Comprobante<select v-model="paymentForm.invoice_id" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950"><option value="">Seleccionar</option><option v-for="invoice in invoices.filter((item) => item.status !== 'canceled' && Number(item.paid_amount) < Number(item.total_amount))" :key="invoice.id" :value="invoice.id">{{ invoice.number }} · saldo {{ currency(Number(invoice.total_amount) - Number(invoice.paid_amount)) }}</option></select></label><label class="text-sm font-medium text-slate-700 dark:text-slate-200">Medio de pago<select v-model="paymentForm.payment_method_id" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950"><option value="">Seleccionar</option><option v-for="method in paymentMethods" :key="method.id" :value="method.id">{{ method.name }}</option></select></label><label class="text-sm font-medium text-slate-700 dark:text-slate-200">Importe<input v-model.number="paymentForm.amount" type="number" min="0.01" step="0.01" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950" /></label><label class="text-sm font-medium text-slate-700 dark:text-slate-200">Referencia<input v-model="paymentForm.reference" type="text" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950" /></label></div><div class="mt-5 flex justify-end"><button type="submit" :disabled="paymentForm.processing" class="min-h-11 rounded-xl bg-clinic-600 px-5 text-sm font-semibold text-white hover:bg-clinic-700 disabled:opacity-60">Registrar cobro</button></div></form>

        <form v-if="cashPanelOpen" class="mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900" @submit.prevent="submitCash"><div class="flex items-start justify-between gap-4"><div><h2 class="font-semibold text-slate-950 dark:text-white">Caja por sede</h2><p class="mt-1 text-sm text-slate-500 dark:text-slate-400">{{ selectedCashRegister?.opened_at ? 'Registrá el efectivo contado para cerrar la caja.' : 'Definí el fondo inicial para abrir la caja.' }}</p></div><button type="button" class="rounded-lg p-2 text-slate-500 hover:bg-slate-100" @click="cashPanelOpen = false"><BaseIcon name="close" class="size-4" /></button></div><div class="mt-5 grid gap-4 md:grid-cols-3"><label class="text-sm font-medium text-slate-700 dark:text-slate-200">Sede<select v-model="cashForm.location_id" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950"><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.name }}</option></select></label><label v-if="!selectedCashRegister?.opened_at" class="text-sm font-medium text-slate-700 dark:text-slate-200">Fondo inicial<input v-model.number="cashForm.opening_amount" type="number" min="0" step="0.01" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950" /></label><label v-else class="text-sm font-medium text-slate-700 dark:text-slate-200">Efectivo contado<input v-model.number="cashForm.counted_amount" type="number" min="0" step="0.01" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950" /></label></div><div class="mt-5 flex justify-end"><button type="submit" :disabled="cashForm.processing" class="min-h-11 rounded-xl bg-clinic-600 px-5 text-sm font-semibold text-white hover:bg-clinic-700 disabled:opacity-60">{{ selectedCashRegister?.opened_at ? 'Cerrar caja' : 'Abrir caja' }}</button></div></form>

        <section class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
            <div class="border-b border-slate-200 p-5 dark:border-slate-800">
                <h2 class="font-semibold text-slate-950 dark:text-white">Últimos comprobantes</h2>
            </div>
            <div class="overflow-x-auto">
                <table class="w-full min-w-175 text-left text-sm">
                    <thead class="bg-slate-50 text-xs tracking-wide text-slate-500 uppercase dark:bg-slate-950/50 dark:text-slate-400"><tr><th class="px-5 py-3">Número</th><th class="px-5 py-3">Tipo</th><th class="px-5 py-3">Estado</th><th class="px-5 py-3 text-right">Total</th><th class="px-5 py-3 text-right">Cobrado</th></tr></thead>
                    <tbody class="divide-y divide-slate-100 dark:divide-slate-800">
                        <tr v-for="invoice in invoices" :key="invoice.id"><td class="px-5 py-4 font-mono font-medium text-slate-950 dark:text-white">{{ invoice.number }}<div v-if="permissions.canCancelInvoices && invoice.status !== 'canceled'" class="mt-1 flex flex-wrap gap-x-3 gap-y-1 font-sans text-xs font-semibold"><button v-if="invoice.type === 'invoice'" type="button" class="text-clinic-700 hover:underline dark:text-clinic-300" @click="openAdjustment(invoice, 'credit-note')">Nota de crédito</button><button v-if="Number(invoice.paid_amount) > 0" type="button" class="text-amber-700 hover:underline dark:text-amber-300" @click="openAdjustment(invoice, 'refund')">Devolver</button><button v-if="Number(invoice.paid_amount) === 0" type="button" class="text-rose-600 hover:underline" @click="cancelTarget = invoice">Anular</button></div></td><td class="px-5 py-4 text-slate-600 dark:text-slate-300">{{ invoice.type === 'credit_note' ? 'Nota de crédito' : invoice.type === 'advance' ? 'Anticipo' : 'Factura' }}<span class="block text-xs text-slate-500">{{ payerLabel(invoice.payer_type) }}{{ invoice.coverage_name ? ` · ${invoice.coverage_name}` : '' }}</span></td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="statusClass(invoice.status)">{{ statusLabel(invoice.status) }}</span></td><td class="px-5 py-4 text-right font-medium text-slate-950 dark:text-white">{{ currency(invoice.total_amount) }}</td><td class="px-5 py-4 text-right text-slate-600 dark:text-slate-300">{{ currency(invoice.paid_amount) }}</td></tr>
                        <tr v-if="!invoices.length"><td colspan="5" class="px-5 py-10 text-center text-slate-500 dark:text-slate-400">Todavía no hay comprobantes emitidos.</td></tr>
                    </tbody>
                </table>
            </div>
        </section>
        <section v-if="permissions.canCancelInvoices && refunds.length" class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900"><div class="border-b border-slate-200 p-5 dark:border-slate-800"><h2 class="font-semibold text-slate-950 dark:text-white">Devoluciones</h2><p class="mt-1 text-sm text-slate-500 dark:text-slate-400">La autorización y el registro quedan separados para conservar el control operativo.</p></div><div class="divide-y divide-slate-100 dark:divide-slate-800"><div v-for="refund in refunds" :key="refund.id" class="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p class="font-mono text-sm font-semibold text-slate-950 dark:text-white">{{ refund.invoice.number }} · {{ currency(refund.amount) }}</p><p class="mt-1 text-sm text-slate-600 dark:text-slate-300">{{ refund.reason }}</p><p class="mt-1 text-xs font-semibold text-amber-700 dark:text-amber-300">{{ refund.status === 'pending' ? 'Pendiente de autorización' : refund.status === 'authorized' ? 'Autorizada; pendiente de registro' : 'Registrada' }}</p></div><div class="flex gap-2"><button v-if="refund.status === 'pending'" type="button" :disabled="refundActionForm.processing" class="min-h-10 rounded-xl border border-clinic-200 px-3 text-sm font-semibold text-clinic-700 hover:bg-clinic-50 disabled:opacity-60 dark:border-clinic-800 dark:text-clinic-300" @click="authorizeRefund(refund)">Autorizar</button><button v-if="refund.status === 'authorized'" type="button" :disabled="refundActionForm.processing" class="min-h-10 rounded-xl bg-clinic-600 px-3 text-sm font-semibold text-white hover:bg-clinic-700 disabled:opacity-60" @click="registerRefund(refund)">Registrar</button></div></div></div></section>
        </template>
        <div v-if="cancelTarget" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4 backdrop-blur-sm"><form class="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900" @submit.prevent="submitCancellation"><h2 class="text-lg font-bold text-slate-950 dark:text-white">Anular {{ cancelTarget.number }}</h2><p class="mt-2 text-sm text-slate-500 dark:text-slate-400">Sólo se pueden anular comprobantes sin cobros registrados.</p><label class="mt-5 block text-sm font-medium text-slate-700 dark:text-slate-200">Motivo<textarea v-model="cancelForm.reason" required rows="3" class="mt-1.5 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-950" /></label><div class="mt-6 flex justify-end gap-3"><button type="button" class="min-h-11 rounded-xl px-4 text-sm font-semibold text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800" @click="cancelTarget = null">Volver</button><button type="submit" :disabled="cancelForm.processing" class="min-h-11 rounded-xl bg-rose-600 px-4 text-sm font-semibold text-white hover:bg-rose-700 disabled:opacity-60">Confirmar anulación</button></div></form></div>
        <div v-if="adjustmentTarget" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4 backdrop-blur-sm"><form class="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900" @submit.prevent="submitAdjustment"><h2 class="text-lg font-bold text-slate-950 dark:text-white">{{ adjustmentType === 'credit-note' ? 'Emitir nota de crédito' : 'Solicitar devolución' }}</h2><p class="mt-2 text-sm text-slate-500 dark:text-slate-400">Comprobante {{ adjustmentTarget.number }} · máximo {{ currency(adjustmentType === 'credit-note' ? adjustmentTarget.total_amount : adjustmentTarget.paid_amount) }}.</p><label class="mt-5 block text-sm font-medium text-slate-700 dark:text-slate-200">Importe<input v-model.number="adjustmentForm.amount" required type="number" min="0.01" step="0.01" class="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 dark:border-slate-700 dark:bg-slate-950" /></label><label class="mt-4 block text-sm font-medium text-slate-700 dark:text-slate-200">Motivo<textarea v-model="adjustmentForm.reason" required rows="3" class="mt-1.5 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-950" /></label><div class="mt-6 flex justify-end gap-3"><button type="button" class="min-h-11 rounded-xl px-4 text-sm font-semibold text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800" @click="adjustmentTarget = null">Volver</button><button type="submit" :disabled="adjustmentForm.processing" class="min-h-11 rounded-xl bg-clinic-600 px-4 text-sm font-semibold text-white hover:bg-clinic-700 disabled:opacity-60">Confirmar</button></div></form></div>

        <template v-if="section === 'accounting'">
            <section class="mt-6 grid gap-4 md:grid-cols-3"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900"><p class="text-sm text-slate-500">Asientos recientes</p><p class="mt-2 text-3xl font-bold text-slate-950 dark:text-white">{{ journalEntries.length }}</p></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900"><p class="text-sm text-slate-500">Cierres registrados</p><p class="mt-2 text-3xl font-bold text-slate-950 dark:text-white">{{ cashClosures.length }}</p></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900"><p class="text-sm text-slate-500">Cuentas activas</p><p class="mt-2 text-3xl font-bold text-slate-950 dark:text-white">{{ accountBalances.length }}</p></article></section>
            <section class="mt-6 grid gap-6 xl:grid-cols-2"><article class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900"><div class="border-b border-slate-200 p-5 dark:border-slate-800"><h2 class="font-semibold text-slate-950 dark:text-white">Balance por cuenta</h2><p class="mt-1 text-sm text-slate-500">Débitos, créditos y saldo acumulado.</p></div><div class="max-h-125 overflow-auto"><table class="w-full text-left text-sm"><thead class="sticky top-0 bg-slate-50 text-xs tracking-wide text-slate-500 uppercase dark:bg-slate-950"><tr><th class="px-5 py-3">Cuenta</th><th class="px-5 py-3 text-right">Débito</th><th class="px-5 py-3 text-right">Crédito</th><th class="px-5 py-3 text-right">Saldo</th></tr></thead><tbody class="divide-y divide-slate-100 dark:divide-slate-800"><tr v-for="account in accountBalances" :key="account.id"><td class="px-5 py-3"><span class="font-mono text-xs text-slate-500">{{ account.code }}</span><span class="ml-2 font-medium text-slate-900 dark:text-white">{{ account.name }}</span></td><td class="px-5 py-3 text-right">{{ currency(account.debits) }}</td><td class="px-5 py-3 text-right">{{ currency(account.credits) }}</td><td class="px-5 py-3 text-right font-semibold">{{ currency(Number(account.debits) - Number(account.credits)) }}</td></tr></tbody></table></div></article><article class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900"><div class="border-b border-slate-200 p-5 dark:border-slate-800"><h2 class="font-semibold text-slate-950 dark:text-white">Libro diario</h2><p class="mt-1 text-sm text-slate-500">Últimos asientos contabilizados.</p></div><div class="max-h-125 divide-y divide-slate-100 overflow-auto dark:divide-slate-800"><div v-for="entry in journalEntries" :key="entry.id" class="p-5"><p class="font-medium text-slate-950 dark:text-white">{{ entry.description }}</p><p class="mt-1 text-xs text-slate-500">{{ entry.entry_date }}</p><div class="mt-3 space-y-1.5 text-sm"><div v-for="line in entry.lines" :key="line.id" class="grid grid-cols-[1fr_auto_auto] gap-3 text-slate-600 dark:text-slate-300"><span>{{ line.account.code }} · {{ line.account.name }}</span><span>{{ Number(line.debit) > 0 ? currency(line.debit) : '—' }}</span><span>{{ Number(line.credit) > 0 ? currency(line.credit) : '—' }}</span></div></div></div><p v-if="!journalEntries.length" class="p-10 text-center text-sm text-slate-500">Todavía no hay asientos para mostrar.</p></div></article></section>
            <section class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900"><div class="border-b border-slate-200 p-5 dark:border-slate-800"><h2 class="font-semibold text-slate-950 dark:text-white">Cierres de caja</h2></div><div class="overflow-x-auto"><table class="w-full min-w-175 text-left text-sm"><thead class="bg-slate-50 text-xs tracking-wide text-slate-500 uppercase dark:bg-slate-950/50"><tr><th class="px-5 py-3">Fecha</th><th class="px-5 py-3 text-right">Inicial</th><th class="px-5 py-3 text-right">Esperado</th><th class="px-5 py-3 text-right">Contado</th><th class="px-5 py-3 text-right">Diferencia</th></tr></thead><tbody class="divide-y divide-slate-100 dark:divide-slate-800"><tr v-for="closure in cashClosures" :key="closure.id"><td class="px-5 py-4">{{ closure.closed_at }}</td><td class="px-5 py-4 text-right">{{ currency(closure.opening_amount) }}</td><td class="px-5 py-4 text-right">{{ currency(closure.expected_amount) }}</td><td class="px-5 py-4 text-right">{{ currency(closure.counted_amount) }}</td><td class="px-5 py-4 text-right font-semibold" :class="Number(closure.difference_amount) === 0 ? 'text-emerald-600' : 'text-rose-600'">{{ currency(closure.difference_amount) }}</td></tr><tr v-if="!cashClosures.length"><td colspan="5" class="px-5 py-10 text-center text-slate-500">Todavía no hay cierres registrados.</td></tr></tbody></table></div></section>
        </template>
    </AppShell>
</template>
